package org.brightstats.stats;

import java.util.*;

/** Shared, disjoint group selection, pooled orientation and comparable PLS/PLSc targets. */
public final class PlsGroups {
    private PlsGroups(){}
    public record Selection(String nameA,String nameB,int[] rowsA,int[] rowsB){
        public Selection{Objects.requireNonNull(rowsA);Objects.requireNonNull(rowsB);rowsA=rowsA.clone();rowsB=rowsB.clone();if(nameA==null||nameB==null||nameA.isBlank()||nameB.isBlank()||nameA.equals(nameB)||rowsA.length<3||rowsB.length<3)throw new IllegalArgumentException("Choose distinct named groups with at least three observations each.");Set<Integer> used=new HashSet<>();for(int[] group:List.of(rowsA,rowsB))for(int row:group)if(row<0||!used.add(row))throw new IllegalArgumentException("Group rows must be nonnegative, unique and disjoint.");}
        @Override public int[] rowsA(){return rowsA.clone();}@Override public int[] rowsB(){return rowsB.clone();}
    }
    public record Group(String name,int[] rows,PlsSem.Fit model,ModelDiagnostics.Fit diagnostics){public Group{rows=rows.clone();}@Override public int[] rows(){return rows.clone();}}
    public record Point(Selection selection,boolean consistent,PlsSem.Options modelOptions,PlsSem.Fit pooled,Group groupA,Group groupB,int excludedRows,List<Bootstrap.Parameter> parameters,List<String> unavailableTargets){public Point{parameters=List.copyOf(parameters);unavailableTargets=List.copyOf(unavailableTargets);}}
    static final class Context {
        final double[][] data,pooledScores,pooledStandardized,withinStandardized;final List<PlsSem.Block> blocks;final List<PlsSem.Edge> edges;final PlsSem.Options modelOptions;final boolean consistent;final Point point;final int[] a,b;final List<Bootstrap.Parameter> base;
        Context(double[][] observations,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Selection selection,boolean consistent){
            Matrices.width(observations,6);this.blocks=List.copyOf(blocks);this.edges=List.copyOf(edges);this.modelOptions=Objects.requireNonNull(options);this.consistent=consistent;int na=selection.rowsA.length,nb=selection.rowsB.length;data=new double[na+nb][];int index=0;for(int[] rows:List.of(selection.rowsA,selection.rowsB))for(int row:rows){if(row>=observations.length)throw new IllegalArgumentException("Group row is outside the prepared data.");data[index++]=observations[row].clone();}a=java.util.stream.IntStream.range(0,na).toArray();b=java.util.stream.IntStream.range(na,na+nb).toArray();PlsSem.Fit pooled=model(data);pooledScores=pooled.scores();pooledStandardized=standardize(data,blocks);double[][] za=standardize(select(data,a),blocks),zb=standardize(select(data,b),blocks);withinStandardized=new double[data.length][];for(int i=0;i<na;i++)withinStandardized[i]=za[i];for(int i=0;i<nb;i++)withinStandardized[na+i]=zb[i];
            Group ga=group(selection.nameA(),a,selection.rowsA),gb=group(selection.nameB(),b,selection.rowsB);base=Bootstrap.parameters(blocks,edges);List<Bootstrap.Parameter> candidates=new ArrayList<>(base);for(int j=0;j<blocks.size();j++){for(String family:List.of("R-square","Adjusted R-square","AVE","Cronbach alpha","rho_A","rho_C"))if(blocks.get(j).columns().length>1||family.equals("R-square")||family.equals("Adjusted R-square"))candidates.add(new Bootstrap.Parameter(family,j,-1,-1,blocks.get(j).name()));}for(var edge:edges)candidates.add(new Bootstrap.Parameter("f-square",edge.source(),edge.target(),-1,blocks.get(edge.source()).name()+" → "+blocks.get(edge.target()).name()));
            List<Bootstrap.Parameter> available=new ArrayList<>();List<String> unavailable=new ArrayList<>();for(var term:candidates){if(Double.isFinite(value(ga,term))&&Double.isFinite(value(gb,term)))available.add(term);else unavailable.add(term.family()+": "+term.label());}point=new Point(selection,consistent,options,pooled,ga,gb,observations.length-data.length,available,unavailable);
        }
        PlsSem.Fit model(double[][] raw){Matrices.interrupted();var fit=consistent?ConsistentPls.fit(raw,blocks,edges,modelOptions).inferenceFit():PlsSem.fit(raw,blocks,edges,modelOptions);if(!fit.converged())throw new IllegalArgumentException("Group PLS estimation did not converge.");return fit;}
        Group group(String name,int[] localRows,int[] sourceRows){double[][] raw=select(data,localRows);PlsSem.Fit fit=model(raw);double[] signs=Bootstrap.alignment(fit.scores(),pooledScores,localRows);double[][] scores=fit.scores(),weights=fit.weights(),loadings=fit.loadings(),paths=fit.pathCoefficients();for(int j=0;j<blocks.size();j++){for(double[] row:scores)row[j]*=signs[j];for(int i=0;i<weights[j].length;i++){weights[j][i]*=signs[j];loadings[j][i]*=signs[j];}for(int k=0;k<blocks.size();k++)paths[j][k]*=signs[j]*signs[k];}var aligned=new PlsSem.Fit(scores,weights,loadings,paths,fit.rSquared(),fit.iterations(),true,fit.finalWeightChange());return new Group(name,sourceRows,aligned,ModelDiagnostics.compute(raw,blocks,edges,aligned));}
        double[] values(Group group){double[] values=new double[point.parameters().size()],common=Bootstrap.values(group.model(),blocks,base,null);for(int i=0;i<values.length;i++){var term=point.parameters().get(i);int index=base.indexOf(term);values[i]=index>=0?common[index]:value(group,term);}if(!Arrays.stream(values).allMatch(Double::isFinite))throw new IllegalArgumentException("A group comparison target is not finite.");return values;}
        private double value(Group group,Bootstrap.Parameter term){
            int j=term.source(),k=term.target();var diagnostics=group.diagnostics();var reliability=diagnostics.reliability()[j];return switch(term.family()){
                case "R-square"->group.model().rSquared()[j];case "Adjusted R-square"->{long predictors=edges.stream().filter(e->e.target()==j).count();int n=group.model().scores().length;yield n>predictors+1?1-(1-group.model().rSquared()[j])*(n-1)/(n-predictors-1):Double.NaN;}
                case "AVE"->reliability.ave();case "Cronbach alpha"->reliability.alpha();case "rho_A"->reliability.rhoA();case "rho_C"->reliability.rhoC();case "f-square"->diagnostics.effectSizes()[j][k];
                default->Bootstrap.values(group.model(),blocks,base,null)[base.indexOf(term)];
            };
        }
        double[] compositions(Group groupA,Group groupB,boolean referenceBasis){double[][] basis=referenceBasis?withinStandardized:pooledStandardized,wa=groupA.model().weights(),wb=groupB.model().weights();double[] result=new double[blocks.size()];for(int j=0;j<result.length;j++){int[] columns=blocks.get(j).columns();double[] sa=new double[data.length],sb=new double[data.length];for(int i=0;i<data.length;i++)for(int k=0;k<columns.length;k++){sa[i]+=basis[i][columns[k]]*wa[j][k];sb[i]+=basis[i][columns[k]]*wb[j][k];}result[j]=correlation(sa,sb);}return result;}
        double[][] pooledMoments(int[] rowsA,int[] rowsB){double[][] values=new double[blocks.size()][2];for(int j=0;j<blocks.size();j++){double[] a=moments(pooledScores,rowsA,j),b=moments(pooledScores,rowsB,j);if(!(a[1]>0)||!(b[1]>0))throw new IllegalArgumentException("Pooled construct scores have no within-group variance.");values[j][0]=a[0]-b[0];values[j][1]=Math.log(a[1])-Math.log(b[1]);}return values;}
    }
    public static Point fit(double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Selection selection,boolean consistent){return new Context(data,blocks,edges,options,selection,consistent).point;}
    static double[][] select(double[][] data,int[] rows){double[][] selected=new double[rows.length][];for(int i=0;i<rows.length;i++)selected[i]=data[rows[i]].clone();return selected;}
    private static double[][] standardize(double[][] data,List<PlsSem.Block> blocks){int[] columns=blocks.stream().flatMapToInt(block->Arrays.stream(block.columns())).distinct().sorted().toArray();double[][] used=new double[data.length][columns.length];for(int i=0;i<data.length;i++)for(int j=0;j<columns.length;j++)used[i][j]=data[i][columns[j]];double[][] normalized=Matrices.standardize(used,true,false).values(),result=new double[data.length][data[0].length];for(int i=0;i<data.length;i++)for(int j=0;j<columns.length;j++)result[i][columns[j]]=normalized[i][j];return result;}
    private static double[] moments(double[][] scores,int[] rows,int column){double mean=0,sum=0;for(int i=0;i<rows.length;i++)mean+=(scores[rows[i]][column]-mean)/(i+1);for(int row:rows)sum+=Math.pow(scores[row][column]-mean,2);return new double[]{mean,sum/rows.length};}
    private static double correlation(double[] a,double[] b){double ma=Arrays.stream(a).average().orElseThrow(),mb=Arrays.stream(b).average().orElseThrow(),aa=0,bb=0,ab=0;for(int i=0;i<a.length;i++){double x=a[i]-ma,y=b[i]-mb;aa+=x*x;bb+=y*y;ab+=x*y;}if(!(aa>0)||!(bb>0))throw new IllegalArgumentException("Undefined composite correlation.");return Math.max(-1,Math.min(1,ab/Math.sqrt(aa*bb)));}
}
